From 877ec79ea9239e5d7bc9db2ac17dc9bf2b973419 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:19:29 +0100
Subject: [PATCH] libnotificationmanager: expire notifications of apps that
 quit

When an app quit after sending a flood of notifications, the popups it
had queued kept showing up one by one. Now its notifications are marked
expired when its D-Bus service goes away, so they only stay in history.

BUG: 486070
---
 .../abstractnotificationsmodel.cpp            | 41 ++++++++++++-------
 1 file changed, 26 insertions(+), 15 deletions(-)

diff --git a/libnotificationmanager/abstractnotificationsmodel.cpp b/libnotificationmanager/abstractnotificationsmodel.cpp
index 2bfd15d12f..85fa416b97 100644
--- a/libnotificationmanager/abstractnotificationsmodel.cpp
+++ b/libnotificationmanager/abstractnotificationsmodel.cpp
@@ -58,32 +58,43 @@ AbstractNotificationsModel::Private::Private(AbstractNotificationsModel *q)
     notificationWatcher.setWatchMode(QDBusServiceWatcher::WatchForUnregistration);

     // When the owning application exits, the actions won't work anymore because the app
-    // isn't listening anymore. Remove the actions in this case.
+    // isn't listening anymore. Remove the actions in this case, and expire its notifications
+    // so that popups it queued up, e.g. a flood of them, aren't shown anymore. Go from the newest
+    // one, so that expiring the visible popups doesn't make queued ones show up for a moment.
     connect(&notificationWatcher, &QDBusServiceWatcher::serviceUnregistered, q, [this, q](const QString &serviceName) {
-        for (int row = 0; row < notifications.size(); ++row) {
+        for (int row = notifications.size() - 1; row >= 0; --row) {
             Notification &notification = notifications[row];

             if (notification.dBusService() != serviceName) {
                 continue;
             }

-            if (notification.actionNames().isEmpty() && !notification.hasDefaultAction() && !notification.hasReplyAction()
-                && !notification.d->hasConfigureAction) {
-                continue;
+            QList<int> roles;
+
+            if (!notification.expired()) {
+                q->stopTimeout(notification.id());
+                notification.setExpired(true);
+                roles.append(Notifications::ExpiredRole);
+            }
+
+            if (!notification.actionNames().isEmpty() || notification.hasDefaultAction() || notification.hasReplyAction()
+                || notification.d->hasConfigureAction) {
+                notification.setActions(QStringList());
+                roles.append({Notifications::ActionNamesRole,
+                              Notifications::ActionLabelsRole,
+                              Notifications::HasDefaultActionRole,
+                              Notifications::DefaultActionLabelRole,
+                              Notifications::HasReplyActionRole,
+                              Notifications::ReplyActionLabelRole,
+                              Notifications::ConfigurableRole});
             }

-            notification.setActions(QStringList());
+            if (roles.isEmpty()) {
+                continue;
+            }

             const QModelIndex idx = q->index(row);
-            Q_EMIT q->dataChanged(idx,
-                                  idx,
-                                  {Notifications::ActionNamesRole,
-                                   Notifications::ActionLabelsRole,
-                                   Notifications::HasDefaultActionRole,
-                                   Notifications::DefaultActionLabelRole,
-                                   Notifications::HasReplyActionRole,
-                                   Notifications::ReplyActionLabelRole,
-                                   Notifications::ConfigurableRole});
+            Q_EMIT q->dataChanged(idx, idx, roles);
         }

         notificationWatcher.removeWatchedService(serviceName);
